+import { openFileTab, saveFileViewerState } from "./file-tab-state.ts";
+
+const tabA = {
+  id: "file:/repo/a.ts",
+  label: "a.ts",
+  filePath: "/repo/a.ts",
+  viewerRevision: 0,
+  viewerState: {
